const DOKU_CONFIG = {
  clientId: 'ISI_CLIENT_ID_SANDBOX_DOKU',
  secretKey: 'ISI_SECRET_KEY_SANDBOX_DOKU',
  checkoutEndpoint: 'https://api-sandbox.doku.com/checkout/v1/payment',
  notificationUrl: 'https://n8n.srv651498.hstgr.cloud/webhook/midtrans-aistaff',
  checkoutDueMinutes: 60,
};

const encoder = new TextEncoder();

function normalizePhone(value) {
  const digits = String(value || '').replace(/\D/g, '');
  if (digits.startsWith('0')) return '62' + digits.slice(1);
  return digits;
}

function isoTimestamp() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

function localInvoiceTimestamp() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Jakarta',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(now).reduce((acc, part) => {
    acc[part.type] = part.value;
    return acc;
  }, {});
  return parts.year + parts.month + parts.day + parts.hour + parts.minute + parts.second;
}

async function sha256Base64(value) {
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(value));
  return Buffer.from(digest).toString('base64');
}

async function hmacSha256Base64(secret, value) {
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(value));
  return Buffer.from(signature).toString('base64');
}

const root = $input.first().json;
const input = root.body || root;

const clientId = String(DOKU_CONFIG.clientId || '').trim();
const secretKey = String(DOKU_CONFIG.secretKey || '').trim();
if (!clientId || clientId === 'ISI_CLIENT_ID_SANDBOX_DOKU') {
  throw new Error('Isi DOKU_CONFIG.clientId di node Build DOKU Request.');
}
if (!secretKey || secretKey === 'ISI_SECRET_KEY_SANDBOX_DOKU') {
  throw new Error('Isi DOKU_CONFIG.secretKey di node Build DOKU Request.');
}

const plans = {
  tier_1: { tierNumber: '1', label: 'Starter', amount: 100000, sku: 'CLE-TIER-1' },
  tier_2: { tierNumber: '2', label: 'Pro', amount: 250000, sku: 'CLE-TIER-2' },
  tier_3: { tierNumber: '3', label: 'Enterprise', amount: 500000, sku: 'CLE-TIER-3' },
};

const planCode = String(input.plan_code || input.plan || 'tier_1').toLowerCase();
const plan = plans[planCode];
if (!plan) throw new Error('Unsupported plan_code: ' + planCode);

const phone = normalizePhone(input.phone_number || input.wa || input.phone);
if (!phone || phone.length < 9 || phone.length > 16) {
  throw new Error('phone_number must use format 628xxxxxxxxxx and max 16 digits.');
}

const bridgeReference = String(input.bridge_reference || crypto.randomUUID());
const timestamp = localInvoiceTimestamp();
const invoiceNumber = ('CLE' + plan.tierNumber + phone + timestamp).slice(0, 64);
const callbackUrlResult = String(input.callback_url_result || input.return_url || ('https://chiefaiofficer.id/pay/return?ref=' + encodeURIComponent(bridgeReference)));
const callbackUrl = String(input.callback_url || 'https://chiefaiofficer.id/pay');
const notificationUrl = DOKU_CONFIG.notificationUrl;
const dueMinutes = Number(DOKU_CONFIG.checkoutDueMinutes || 60);

const body = {
  order: {
    amount: plan.amount,
    invoice_number: invoiceNumber,
    currency: 'IDR',
    callback_url: callbackUrl,
    callback_url_result: callbackUrlResult,
    auto_redirect: true,
    line_items: [
      {
        id: planCode,
        name: 'Clevio AI Staff ' + plan.label,
        quantity: 1,
        price: plan.amount,
        sku: plan.sku,
        category: 'digital-content',
      },
    ],
  },
  payment: {
    payment_due_date: dueMinutes,
  },
  customer: {
    id: phone,
    name: 'Clevio Customer',
    phone,
  },
  additional_info: {
    override_notification_url: notificationUrl,
  },
};

const bodyString = JSON.stringify(body);
const requestTarget = '/checkout/v1/payment';
const requestTimestamp = isoTimestamp();
const requestId = ('CLE-' + bridgeReference).replace(/[^a-zA-Z0-9-]/g, '').slice(0, 128);
const digest = await sha256Base64(bodyString);
const signatureComponent = [
  'Client-Id:' + clientId,
  'Request-Id:' + requestId,
  'Request-Timestamp:' + requestTimestamp,
  'Request-Target:' + requestTarget,
  'Digest:' + digest,
].join('\n');
const signature = 'HMACSHA256=' + await hmacSha256Base64(secretKey, signatureComponent);

return [
  {
    json: {
      endpoint: DOKU_CONFIG.checkoutEndpoint,
      headers: {
        clientId,
        requestId,
        requestTimestamp,
        signature,
      },
      bodyString,
      merchant_context: {
        event: 'clevio_payment_create_checkout',
        bridge_reference: bridgeReference,
        phone_number: phone,
        plan_code: planCode,
        plan_label: plan.label,
        amount: plan.amount,
        invoice_number: invoiceNumber,
        callback_url_result: callbackUrlResult,
        notification_url: notificationUrl,
        created_at: new Date().toISOString(),
      },
    },
  },
];

const response = $input.first().json;
const context = $('Build DOKU Request').first().json.merchant_context;
const paymentUrl = response?.response?.payment?.url || response?.payment?.url || response?.payment_url || response?.url;

if (!paymentUrl) {
  throw new Error(`DOKU response does not contain payment URL: ${JSON.stringify(response)}`);
}

return [
  {
    json: {
      payment_url: paymentUrl,
      invoice_number: context.invoice_number,
      bridge_reference: context.bridge_reference,
      phone_number: context.phone_number,
      plan_code: context.plan_code,
      plan_label: context.plan_label,
      amount: context.amount,
      doku_response: response,
    },
  },
];
